{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C22"],
      "claim": "Brigatinib, the highest-transfer analogue, has an absolute oral bioavailability of 46% in healthy volunteers, directly supporting F >= 20% for a structurally related heteroaromatic amine drug-like molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Alizapride, a moderately transferred basic benzamide, shows about 90% systemic availability after oral dosing, supporting high oral bioavailability for ionizable amine/heteroaromatic compounds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "LY2196044, a pyridine-ether/amide analogue, has an estimated absolute bioavailability of 45% in humans, supporting high F for a scaffold with similar polar heterocycles and basic amine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "UK-224,671, a high-transfer analogue, has only 3.6% oral bioavailability in humans, providing affirmative contradictory evidence for low F.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C37"],
      "claim": "Lurasidone, a high-transfer lipophilic antipsychotic, has about 10% fasted bioavailability, providing contradictory evidence for low F.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "SRT2104, a moderate-transfer heteroaromatic amide, has 13.8% absolute oral bioavailability, providing contradictory evidence for low F.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Weighing transfer scores and structural relevance, the highest-scored evidence (brigatinib, 46% F) and multiple moderate-scored oral drugs with similar ionizable amine/heteroaromatic scaffolds (28-90% F) outweigh the high-scored low-F analogues (UK-224,671, lurasidone, SRT2104), whose poor F is associated with lipophilicity and solubility features not shared by the query. Prediction: high.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the query molecule.",
    "Conflicting high-transfer low-F evidence creates uncertainty.",
    "Unknown effects of efflux transporters and first-pass metabolism on this specific scaffold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

